export type Badge = 'hat-trick' | 'on-fire' | 'a-la-escuadra';

export function streakBadge(verdicts: boolean[]): Badge | null {
  let run = 0;
  let best = 0;
  for (const right of verdicts) {
    run = right ? run + 1 : 0;
    best = Math.max(best, run);
  }
  if (best >= 10) return 'a-la-escuadra';
  if (best >= 5) return 'on-fire';
  return best >= 3 ? 'hat-trick' : null;
}

import { describe, expect, it } from 'vitest';
import { streakBadge } from '../streakBadges.ts';

describe('streakBadge', () => {
  it('gives no badge under 3 in a row', () => {
    expect(streakBadge([true, true, false, true, true])).toBeNull();
  });

  it('gives a hat-trick at 3 in a row', () => {
    expect(streakBadge([false, true, true, true, false])).toBe('hat-trick');
  });

  it('gives on fire at 5 in a row', () => {
    expect(streakBadge([true, true, true, true, true, false])).toBe('on-fire');
  });

  it('gives a la escuadra at 10 in a row', () => {
    expect(streakBadge(Array.from({ length: 10 }, () => true))).toBe('a-la-escuadra');
  });
});
